<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
use Illuminate\Database\Capsule\Manager as Capsule;
$id_entitas = po_id_entitas();
$id = (int) ($_GET['id'] ?? 0);
$no = trim((string) ($_GET['no'] ?? ''));
$no_hp = trim((string) ($_GET['no_hp'] ?? ''));
$pesanan = null;
if ($id > 0 || $no !== '') {
    $q = Capsule::table('tb_pesanan_penjualan as pp')
        ->join('tb_pelanggan as p', 'p.id_pelanggan', '=', 'pp.id_pelanggan')
        ->where('pp.id_entitas', $id_entitas);
    if ($id > 0) $q->where('pp.id_pesanan_penjualan', $id); else $q->where('pp.no_pesanan_penjualan', $no);
    $pesanan = $q->select(['pp.*','p.nama_pelanggan','p.no_hp'])->first();
    if ($pesanan && $no_hp === '') $no_hp = (string) $pesanan->no_hp;
}
?>
