dow:0 8px 18px rgba(15,23,42,.06)}.bubble.customer{margin-left:auto;background:linear-gradient(135deg,var(--blue),var(--purple));color:#fff;border-bottom-right-radius:6px}.bubble.admin{margin-right:auto;background:#fff;border:1px solid var(--line);border-bottom-left-radius:6px}.time{font-size:11px;opacity:.65;margin-top:4px}.empty{background:#fff;border:1px dashed #cbd5e1;border-radius:18px;padding:18px;text-align:center;color:#64748b}.composer{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-top:1px solid var(--line);background:#fff}.composer textarea{resize:none;border:1px solid #cbd5e1;border-radius:22px;padding:13px 15px;font:inherit;outline:0}.composer textarea:focus{border-color:var(--purple);box-shadow:0 0 0 4px rgba(124,58,237,.10)}.composer button{border:0;border-radius:999px;background:linear-gradient(135deg,var(--orange),var(--purple));color:#fff;font-weight:900;padding:0 20px}@media(max-width:640px){.bubble{max-width:88%}.composer{grid-template-columns:1fr}.composer button{padding:12px}}
</style></head><body><div class="phone"><div class="top"><div><h1>Chat Pesanan</h1><div class="meta" id="orderMeta"><?= $pesanan ? po_esc($pesanan->no_pesanan_penjualan) : 'Cari pesanan' ?></div></div><a href="<?= po_esc(po_url('cek.php?no_hp=' . urlencode($no_hp) . '&entitas=' . (int) $id_entitas)) ?>">Kembali</a></div>
<?php if (!$pesanan): ?><div class="verify"><form method="get" action="<?= po_esc(po_url('chat.php')) ?>"><input type="hidden" name="entitas" value="<?= (int) $id_entitas ?>"><input type="text" name="no" value="<?= po_esc($no) ?>" placeholder="No pesanan" required><input type="text" name="no_hp" value="<?= po_esc($no_hp) ?>" placeholder="No HP saat checkout" required><button class="btn" type="submit">Buka Chat</button></form></div><?php else: ?>
<div class="products" id="chatProducts"></div><div class="quick"><button type="button" onclick="fillChat('Pesanan saya sudah sampai tahap mana?')">Status pesanan</button><button type="button" onclick="fillChat('Bukti pembayaran saya sudah diterima?')">Bukti pembayaran</button><button type="button" onclick="fillChat('Kapan pesanan saya diproses?')">Kapan diproses?</button><button type="button" onclick="fillChat('Saya mau tanya stok produk di pesanan ini.')">Stok produk</button></div><div class="chat-body" id="chatRows"><div class="empty">Memuat chat...</div></div><form class="composer" id="chatForm"><textarea id="chatText" rows="1" placeholder="Tulis pesan..." required></textarea><button type="submit">Kirim</button></form>
<script>
const ENTITAS_ID=<?= (int)$id_entitas ?>, activeChatId=<?= (int)$pesanan->id_pesanan_penjualan ?>, activeChatPhone=<?= json_encode($no_hp) ?>;function esc(t){return String(t||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}function fillChat(t){document.getElementById('chatText').value=t;document.getElementById('chatText').focus();}async function loadChat(){const res=await fetch(`<?= po_esc(po_url('chat_ajax.php')) ?>?id=${activeChatId}&no_hp=${encodeURIComponent(activeChatPhone)}&entitas=${ENTITAS_ID}`);const data=await res.json();if(!data.ok){document.getElementById('chatRows').innerHTML=`<div class="empty">${esc(data.message)}</div>`;return;}document.getElementById('orderMeta').textContent=data.pesanan.no;document.getElementById('chatProducts').innerHTML=(data.produk||[]).map(p=>`<button class="prod-chip" type="button" onclick="fillChat('Saya mau tanya produk ${esc(p.nama_produk)}.')">🍬 ${esc(p.nama_produk)} · ${esc(p.qty)} x ${esc(p.harga)}</button>`).join('')||'<span class="empty">Produk belum terbaca</span>';document.getElementById('chatRows').innerHTML=(data.rows||[]).map(r=>`<div class="bubble ${r.pengirim_tipe==='customer'?'customer':'admin'}"><strong>${r.pengirim_tipe==='customer'?'Anda':esc(r.nama_pengirim||'Admin')}</strong><br>${esc(r.pesan).replace(/\n/g,'<br>')}<div class="time">${esc(r.tanggal)}</div></div>`).join('')||'<div class="empty">Belum ada chat. Silakan kirim pertanyaan.</div>';const body=document.getElementById('chatRows');body.scrollTop=body.scrollHeight;}document.getElementById('chatForm').addEventListener('submit',async function(e){e.preventDefault();const pesan=document.getElementById('chatText').value.trim();if(!pesan)return;const fd=new FormData();fd.append('id_pesanan_penjualan',activeChatId);fd.append('no_hp',activeChatPhone);fd.append('entitas',ENTITAS_ID);fd.append('pesan',pesan);const res=await fetch(`<?= po_esc(po_url('chat_ajax.php')) ?>`,{method:'POST',body:fd});const data=await res.json();if(!data.ok){alert(data.message);return;}document.getElementById('chatText').value='';await loadChat();});loadChat();
</script><?php endif; ?></div></body></html>
